'use strict';

const { Store } = require('./store');
const { KeyedLock } = require('./keyed-lock');
const {
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
} = require('./errors');

const DEFAULT_TTL_MS = 15 * 60 * 1000;

// Locks belong to the store, not to a service instance, so services built
// over the same store in one process still exclude each other.
const locksByStore = new WeakMap();

// How settling an order changes the counters of each SKU it holds.
const SETTLE = {
  committed: (item, qty) => ({ ...item, stock: item.stock - qty, reserved: item.reserved - qty, sold: item.sold + qty }),
  released: (item, qty) => ({ ...item, reserved: item.reserved - qty })
};

/**
 * Stock reservations for checkout.
 *
 * Every SKU has three counters: `stock` (units on hand), `reserved` (units
 * held for orders that have not been committed) and `sold`. Available stock
 * is `stock - reserved` and must never go below zero.
 *
 * An order moves reserved -> committed, or reserved -> released. Committing
 * turns its held units into sold units; releasing returns them.
 *
 * The service is called concurrently by every checkout worker. The store has
 * no transactions, so each read-modify-write runs under a per-key lock. A call
 * holds at most its order's lock and one SKU's lock at a time, and never waits
 * for another lock while it holds a SKU's, so it only waits for calls that
 * share its order or one of its SKUs.
 *
 * The locks live in this process and are attached to the store object, so
 * every service over the same data must be given the same store object.
 */
class InventoryService {
  #locks;

  constructor({ store = new Store(), reservationTtlMs = DEFAULT_TTL_MS, now = () => Date.now() } = {}) {
    this.store = store;
    this.ttl = reservationTtlMs;
    this.now = now;
    this.#locks = locksFor(store);
  }

  /** Add units to a SKU, creating it if needed. Returns the SKU snapshot. */
  async addStock(sku, qty) {
    assertSku(sku);
    assertQty(qty);
    return this.#locks.run(skuKey(sku), async () => {
      const item = (await this.store.get(skuKey(sku))) || { stock: 0, reserved: 0, sold: 0 };
      const updated = { ...item, stock: item.stock + qty };
      await this.store.set(skuKey(sku), updated);
      return { sku, ...updated };
    });
  }

  /** Units that can still be reserved. */
  async available(sku) {
    const item = await this.getItem(sku);
    return item.stock - item.reserved;
  }

  /** The SKU's counters. */
  async snapshot(sku) {
    const item = await this.getItem(sku);
    return { sku, stock: item.stock, reserved: item.reserved, sold: item.sold };
  }

  /**
   * Hold stock for an order: all of its items, or none of them.
   *
   * Idempotent by orderId: checkout retries a timed-out request with the same
   * orderId, and a retry must return the existing reservation rather than
   * hold the stock twice.
   *
   * Rejects with InsufficientStockError when any item cannot be held, and
   * then holds nothing.
   *
   * A bundle is checked in full before anything is held, then held one SKU at
   * a time. If a concurrent order takes a later item's last units in between,
   * the earlier holds are returned before the call rejects; other callers can
   * see them until then.
   */
  async reserve(orderId, items) {
    assertOrderId(orderId);
    assertItems(items);
    const lines = items.map(({ sku, qty }) => ({ sku, qty }));
    return this.#locks.run(orderKey(orderId), async () => {
      const existing = await this.store.get(orderKey(orderId));
      if (existing) {
        return toReservation(existing);
      }
      // A single item is checked under its lock below; checking a bundle up
      // front keeps the usual rejection from holding anything, even briefly.
      if (lines.length > 1) {
        for (const { sku, qty } of lines) {
          assertAvailable(await this.getItem(sku), sku, qty);
        }
      }
      const held = [];
      try {
        for (const line of lines) {
          await this.#locks.run(skuKey(line.sku), async () => {
            const item = await this.getItem(line.sku);
            assertAvailable(item, line.sku, line.qty);
            await this.store.set(skuKey(line.sku), { ...item, reserved: item.reserved + line.qty });
          });
          held.push(line);
        }
        const order = { orderId, items: lines, status: 'reserved', createdAt: this.now() };
        await this.store.set(orderKey(orderId), order);
        return toReservation(order);
      } catch (err) {
        // All or nothing: give back what this call held, the same change as a release.
        await this.#applyToSkus(held, SETTLE.released);
        throw err;
      }
    });
  }

  /**
   * Turn a reservation into a sale. Idempotent: committing a committed order
   * returns it unchanged. A released order cannot be committed.
   */
  async commit(orderId) {
    assertOrderId(orderId);
    return this.#locks.run(orderKey(orderId), async () => {
      const order = await this.getOrder(orderId);
      if (order.status === 'committed') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'commit');
      }
      return toReservation(await this.#settle(order, 'committed'));
    });
  }

  /**
   * Cancel a reservation and return its units. Idempotent: releasing a
   * released order returns it unchanged. A committed order cannot be
   * released; its units have been sold.
   */
  async release(orderId) {
    assertOrderId(orderId);
    return this.#locks.run(orderKey(orderId), async () => {
      const order = await this.getOrder(orderId);
      if (order.status === 'released') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'release');
      }
      return toReservation(await this.#settle(order, 'released'));
    });
  }

  /**
   * Release every reservation older than the TTL that has not been committed
   * or released. Returns the orderIds it released.
   */
  async expire() {
    const cutoff = this.now() - this.ttl;
    const isStale = order => order.status === 'reserved' && order.createdAt < cutoff;
    const released = [];
    // One order at a time, so the sweep never holds more than one order's
    // locks and does not crowd out checkout on hot SKUs.
    for (const key of await this.store.keys('order:')) {
      // The unlocked read skips settled orders cheaply; the re-read under the
      // lock catches an order a worker committed or released in between.
      if (!isStale(await this.store.get(key))) {
        continue;
      }
      const order = await this.#locks.run(key, async () => {
        const current = await this.store.get(key);
        return isStale(current) ? this.#settle(current, 'released') : null;
      });
      if (order) {
        released.push(order.orderId);
      }
    }
    return released;
  }

  // Moves a reserved order to `status` and applies it to the SKU counters.
  // The caller must hold the order's lock and have checked it is reserved.
  async #settle(order, status) {
    await this.#applyToSkus(order.items, SETTLE[status]);
    const settled = { ...order, status };
    await this.store.set(orderKey(order.orderId), settled);
    return settled;
  }

  // Applies `change` to the SKU of each line, locking one SKU at a time. Each
  // SKU's change stands alone, and the caller's order lock is what stops it
  // being applied twice.
  async #applyToSkus(lines, change) {
    for (const { sku, qty } of lines) {
      await this.#locks.run(skuKey(sku), async () => {
        const item = await this.getItem(sku);
        await this.store.set(skuKey(sku), change(item, qty));
      });
    }
  }

  async getItem(sku) {
    assertSku(sku);
    const item = await this.store.get(skuKey(sku));
    if (!item) {
      throw new UnknownSkuError(sku);
    }
    return item;
  }

  async getOrder(orderId) {
    assertOrderId(orderId);
    const order = await this.store.get(orderKey(orderId));
    if (!order) {
      throw new UnknownOrderError(orderId);
    }
    return order;
  }
}

function locksFor(store) {
  let locks = locksByStore.get(store);
  if (!locks) {
    locks = new KeyedLock();
    locksByStore.set(store, locks);
  }
  return locks;
}

function skuKey(sku) {
  return `sku:${sku}`;
}

function orderKey(orderId) {
  return `order:${orderId}`;
}

function toReservation(order) {
  return { orderId: order.orderId, status: order.status, items: order.items.map(({ sku, qty }) => ({ sku, qty })) };
}

function assertSku(sku) {
  if (typeof sku !== 'string' || sku.trim() === '') {
    throw new ValidationError('sku must be a non-empty string');
  }
}

function assertOrderId(orderId) {
  if (typeof orderId !== 'string' || orderId.trim() === '') {
    throw new ValidationError('orderId must be a non-empty string');
  }
}

function assertAvailable(item, sku, qty) {
  const free = item.stock - item.reserved;
  if (free < qty) {
    throw new InsufficientStockError(sku, qty, free);
  }
}

function assertQty(qty) {
  if (!Number.isInteger(qty) || qty <= 0) {
    throw new ValidationError('qty must be a positive integer');
  }
}

function assertItems(items) {
  if (!Array.isArray(items) || items.length === 0) {
    throw new ValidationError('items must be a non-empty array');
  }
  const seen = new Set();
  for (const entry of items) {
    if (!entry || typeof entry !== 'object') {
      throw new ValidationError('each item must be an object with sku and qty');
    }
    assertSku(entry.sku);
    assertQty(entry.qty);
    if (seen.has(entry.sku)) {
      throw new ValidationError(`duplicate sku in items: ${entry.sku}`);
    }
    seen.add(entry.sku);
  }
}

module.exports = { InventoryService, DEFAULT_TTL_MS };
'use strict';

class InventoryError extends Error {
  constructor(message, code) {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
  }
}

class ValidationError extends InventoryError {
  constructor(message) {
    super(message, 'VALIDATION');
  }
}

class UnknownSkuError extends InventoryError {
  constructor(sku) {
    super(`unknown sku: ${sku}`, 'UNKNOWN_SKU');
    this.sku = sku;
  }
}

class UnknownOrderError extends InventoryError {
  constructor(orderId) {
    super(`unknown order: ${orderId}`, 'UNKNOWN_ORDER');
    this.orderId = orderId;
  }
}

class InsufficientStockError extends InventoryError {
  constructor(sku, requested, available) {
    super(`insufficient stock for ${sku}: requested ${requested}, available ${available}`, 'INSUFFICIENT_STOCK');
    this.sku = sku;
    this.requested = requested;
    this.available = available;
  }
}

class OrderStateError extends InventoryError {
  constructor(orderId, status, action) {
    super(`cannot ${action} order ${orderId}: it is ${status}`, 'ORDER_STATE');
    this.orderId = orderId;
    this.status = status;
  }
}

module.exports = {
  InventoryError,
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
};
'use strict';

/**
 * In-process mutual exclusion per string key. Callers on different keys never
 * wait for each other; callers on the same key run one at a time, in the
 * order they called. A key is tracked only while someone holds or waits for
 * it, so memory follows the number of busy keys, not the size of the catalog.
 *
 * Locks are not re-entrant: a caller that already holds a key and asks for it
 * again waits for itself forever.
 */
class KeyedLock {
  constructor() {
    this.tails = new Map();
  }

  /** Number of keys currently held or waited for. */
  get size() {
    return this.tails.size;
  }

  /** Run `fn` while holding `key`, and free the key when `fn` settles. */
  async run(key, fn) {
    const previous = this.tails.get(key) || Promise.resolve();
    let free;
    const held = new Promise(resolve => { free = resolve; });
    const tail = previous.then(() => held);
    this.tails.set(key, tail);
    try {
      await previous;
      return await fn();
    } finally {
      if (this.tails.get(key) === tail) {
        this.tails.delete(key);
      }
      free();
    }
  }
}

module.exports = { KeyedLock };
'use strict';

// In-memory key-value store with the latency profile of the Redis cluster
// used in production: every call yields to the event loop before it reads or
// writes, so concurrent callers interleave the way they do against the real
// store. Values are copied on the way in and out.
class Store {
  constructor() {
    this.data = new Map();
  }

  async get(key) {
    await tick();
    const value = this.data.get(key);
    return value === undefined ? undefined : structuredClone(value);
  }

  async set(key, value) {
    await tick();
    this.data.set(key, structuredClone(value));
  }

  async keys(prefix) {
    await tick();
    return [...this.data.keys()].filter(key => key.startsWith(prefix));
  }
}

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

module.exports = { Store };
