# INC-5521: Oversold stock and stuck holds during the September flash sale

Reported by the checkout team after the 2026-09-12 flash sale.

## What we saw

- The `sneaker-limited` drop had 250 units. We confirmed 263 orders, and 13
  customers had to be refunded.
- The stock dashboard showed `reserved` going negative for two SKUs after the
  sale, and it has not recovered.
- Some customers who retried checkout after a timeout had units held twice for
  one order; the second hold only disappeared when the reservation expired.
- One order was rejected because a bundle item was out of stock, but the other
  item in the bundle stayed held until we restarted the worker pool.
- Finance reports `sold` counts that are higher than the number of orders we
  shipped for a few SKUs.

## Context

Every checkout worker calls `InventoryService` concurrently. During the sale
we ran 40 workers. The nightly `expire()` job ran once during the sale.

The unit tests all pass, and none of this reproduces when we click through
checkout by hand.

A service-wide lock (INC-5490) stopped the overselling in staging but cut
checkout throughput by 90% and was rolled back the same day.
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  InsufficientStockError,
  UnknownSkuError,
  UnknownOrderError,
  ValidationError,
  OrderStateError,
  Store
} = require('../src');

async function service(stock = { widget: 10 }) {
  const svc = new InventoryService();
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

test('addStock creates and tops up a sku', async () => {
  const svc = new InventoryService();
  assert.deepEqual(await svc.addStock('widget', 5), { sku: 'widget', stock: 5, reserved: 0, sold: 0 });
  assert.deepEqual(await svc.addStock('widget', 2), { sku: 'widget', stock: 7, reserved: 0, sold: 0 });
});

test('reserve holds stock and commit sells it', async () => {
  const svc = await service();
  const reservation = await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
  assert.deepEqual(reservation, { orderId: 'o1', status: 'reserved', items: [{ sku: 'widget', qty: 3 }] });
  assert.equal(await svc.available('widget'), 7);
  await svc.commit('o1');
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
});

test('release returns held stock', async () => {
  const svc = await service();
  await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
  const released = await svc.release('o1');
  assert.equal(released.status, 'released');
  assert.equal(await svc.available('widget'), 10);
});

test('reserve is idempotent for a retried order', async () => {
  const svc = await service();
  await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
  await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
  assert.equal(await svc.available('widget'), 8);
});

test('reserve rejects when stock is short', async () => {
  const svc = await service({ widget: 1 });
  await assert.rejects(svc.reserve('o1', [{ sku: 'widget', qty: 2 }]), InsufficientStockError);
});

test('unknown skus and bad input are rejected', async () => {
  const svc = await service();
  await assert.rejects(svc.reserve('o1', [{ sku: 'nope', qty: 1 }]), UnknownSkuError);

