// Starts call i after i event-loop turns, so each call lands at a different
// point of the calls already in flight. Calls that all start on the same turn
// hit identical interleavings and can hide a double apply behind a lost update.
function staggered(count, call) {
  return Promise.allSettled(Array.from({ length: count }, (_, i) => turns(i).then(call)));
}

async function settlesWithin(promise, ms, what) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(`${what} did not settle within ${ms}ms`)), ms);
  });
  try {
    return await Promise.race([promise, timeout]);
  } finally {
    clearTimeout(timer);
  }
}

// Asserts that exactly one of two racing calls on the same order won, the
// loser was rejected as an OrderStateError, and returns the winner's index.
function oneWinner(results) {
  const { fulfilled, rejected } = settled(results);
  assert.equal(fulfilled.length, 1, 'exactly one of the racing calls should succeed');
  assert.ok(rejected[0] instanceof OrderStateError, `loser should get OrderStateError, got ${rejected[0]}`);
  return results.findIndex(r => r.status === 'fulfilled');
}

test('263 concurrent orders for 250 units confirm exactly 250 and sell 250', async () => {
  const svc = await service({ 'sneaker-limited': 250 });
  const results = await Promise.allSettled(
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
