describe('adjustStock under checkout traffic', () => {
  test('concurrent adjustments and addStock calls keep every unit', async () => {
    const svc = await service({ widget: 100 });
    const calls = Array.from({ length: 60 }, (_, i) => {
      if (i % 3 === 0) return () => svc.adjustStock('widget', 2, 'count');
      if (i % 3 === 1) return () => svc.adjustStock('widget', -1, 'count');
      return () => svc.addStock('widget', 3);
    });
    const { rejected } = settled(await staggered(calls.length, function () { return calls.shift()(); }));
    assert.equal(rejected.length, 0);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 100 + 20 * 2 - 20 + 20 * 3, reserved: 0, sold: 0 });
  });

  test('removals racing reservations never take stock below reserved', async () => {
    const svc = await service({ widget: 20 });
    const calls = [];
    for (let i = 0; i < 20; i++) {
      calls.push(() => svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]));
      calls.push(() => svc.adjustStock('widget', -2, 'count'));
    }
    let next = 0;
    const results = await staggered(calls.length, () => calls[next++]());
    for (const r of results) {
      if (r.status === 'rejected') {
        assert.ok(r.reason instanceof InsufficientStockError, `unexpected rejection: ${r.reason && r.reason.stack}`);
      }
    }
    const snap = await svc.snapshot('widget');
    const reservedOrders = results.filter((r, i) => i % 2 === 0 && r.status === 'fulfilled').length;
    const removals = results.filter((r, i) => i % 2 === 1 && r.status === 'fulfilled').length;
    assert.equal(snap.reserved, reservedOrders);
    assert.equal(snap.stock, 20 - 2 * removals);
    assert.ok(snap.stock >= snap.reserved, `stock ${snap.stock} fell below reserved ${snap.reserved}`);
  });

  test('a commit and a release settling while counts are corrected keep the counters exact', async () => {
    const svc = await service({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
    await svc.reserve('o2', [{ sku: 'widget', qty: 2 }]);
    let next = 0;
    const calls = [
      () => svc.commit('o1'),
      () => svc.adjustStock('widget', -4, 'count'),
      () => svc.release('o2'),
      () => svc.adjustStock('widget', 6, 'count')
    ];
    const { rejected } = settled(await staggered(calls.length, () => calls[next++]()));
    assert.equal(rejected.length, 0);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10 - 3 - 4 + 6, reserved: 0, sold: 3 });
  });

  test('an adjustment does not wait for callers of other SKUs', async () => {
    const store = new Store();
    const svc = await service({ busy: 5, quiet: 5 }, { store });
    const realGet = store.get.bind(store);
    let release;
    const gate = new Promise(resolve => { release = resolve; });
    store.get = async key => {
      if (key === 'sku:busy') await gate;
      return realGet(key);
    };
    const stuck = svc.adjustStock('busy', 1, 'count');
    try {
      const snap = await settlesWithin(svc.adjustStock('quiet', 1, 'count'), 1000, 'adjustStock on another SKU');
      assert.equal(snap.stock, 6);
    } finally {
      release();
      await stuck;
    }
  });
});
